Pc = {1:8,5:2,8:5,9:2,10:2,12:2}
seq = {}
for r,c in Pc.items():
    seq[r%6] = c
pred = [seq[i%6] for i in range(14)]
actual = [2,8,5,2,2,2,2,8,5,2,2,2,2,8]
