colored = {0:5, 4:3, 20:7}
def find_p(colored):
    for p in range(1, 31):
        res = [r % p for r in colored]
        if len(set(res)) == len(colored) == p and set(res) == set(range(p)):
            diffs_ok = all((b-a) % p != 0 for a in colored for b in colored if a != b)
            if diffs_ok:
                return p
    return None
p = find_p(colored)
print("test period:", p)
Pseq = {r % p: c for r, c in colored.items()}
grid = [[Pseq[i % p] for _ in range(28)] for i in range(28)]
print(grid[0][:6], grid[1][:6], grid[2][:6])
import json
json.dump(grid, open('ans.json','w'))

